  "你好！我可以解答平台使用问题，帮你把工作流搭起来。当前项目里已安装的 GitHub 等 HTTP MCP 会由服务端代调。平台写入按下方审批模式处理：默认转为草稿逐个确认；切换到「帮我批准」或「自动执行」后，AI 会直接调用平台写入工具，自动执行模式下一次性完成全部步骤。": "Xin chào! Tôi có thể trả lời câu hỏi về nền tảng và giúp xây dựng quy trình. HTTP MCP đã cài trong dự án hiện tại, như GitHub, được máy chủ gọi thay bạn. Thao tác ghi nền tảng tuân chế độ phê duyệt bên dưới: mặc định thành bản nháp để bạn xác nhận từng mục; chuyển sang “Phê duyệt thay tôi” hoặc “Tự động chạy”, AI gọi trực tiếp công cụ ghi nền tảng; chế độ tự động hoàn thành mọi bước trong một lượt.",
