  "当前项目还没有角色，请只用 approval（人工确认）和 script 节点。": "Dự án hiện tại chưa có vai trò. Chỉ dùng bước approval (con người phê duyệt) và script.",
  "当前项目可用角色（agentId：名称）：\\n": "Vai trò khả dụng trong dự án hiện tại (agentId: name):\\n",
  "构建静态站点": "Build trang tĩnh",
  "在当前画布上的这份 SOP 上按要求修改，重新提交完整的 workflows_save 草稿。这是增量修改：用户没点名的节点、连线、id 和脚本都保持原样，不要另起一条流程。": "Sửa SOP hiện trên canvas theo yêu cầu và gửi lại bản nháp workflows_save đầy đủ. Đây là chỉnh sửa tăng dần: giữ nguyên mọi bước, cạnh, ID và tập lệnh mà người dùng không đề cập. Không tạo SOP riêng.",
  "请在当前项目搭建一条新的 SOP。": "Xây dựng SOP mới trong dự án hiện tại.",
  "只提交一个 workflows_save 草稿，不要发布，也不要调用其它写入工具。": "Chỉ gửi một bản nháp workflows_save. Không phát hành hoặc gọi công cụ ghi khác.",
  "必须是 JSON 对象（不要序列化成字符串），字段按 name、description、nodes、edges 的顺序输出；已有节点沿用原来的 id，只有新增节点才用新 id。": "Phải là đối tượng JSON (không tuần tự hóa thành chuỗi), với các trường theo thứ tự name, description, nodes, edges; bước hiện có giữ ID gốc, chỉ bước mới nhận ID mới.",
  "节点的 agentId 只能从下面的已有角色里选；没有合适角色时改用 approval（人工确认）或 script 节点。": "agentId của bước phải thuộc một trong các vai trò hiện có bên dưới; nếu không có vai trò phù hợp, dùng bước approval (con người phê duyệt) hoặc script.",
  "平台节点「构建静态站点」不在角色列表里：id 固定为 af-preview-build，agentId 为 af-preview-builder。复制或修改已有 SOP 时必须保留它、它的连线和 preview 字段，除非用户明确要求去掉前端预览。": "Bước nền tảng “Build trang tĩnh” không nằm trong danh sách vai trò: id cố định là af-preview-build, agentId là af-preview-builder. Khi sao chép hoặc sửa SOP hiện có, giữ bước này, các cạnh và trường preview trừ khi người dùng yêu cầu rõ bỏ bản xem trước frontend.",
  "用": "Dùng ",
