  "工具列表出现即接入成功": "Đã kết nối khi danh sách công cụ xuất hiện",
  "获取 Run ID，再用": "Lấy ID lượt chạy, sau đó dùng ",
  "不要提交到代码仓库；怀疑泄露时立即撤销。": "Không commit vào kho mã; thu hồi ngay nếu nghi bị lộ.",
  "配置提示词已复制，可直接发给 Agent": "Đã sao chép prompt thiết lập. Gửi cho tác tử của bạn",
  "请检查登录状态或网络连接": "Kiểm tra trạng thái đăng nhập hoặc kết nối mạng",
  "搜索工具名、路径或说明": "Tìm tên công cụ, đường dẫn hoặc mô tả",
  "个人 Token 必须绑定到登录用户。": "Token cá nhân phải gắn với người dùng đã đăng nhập.",
  "已创建，可直接复制完整配置提示词": "Đã tạo. Sao chép prompt thiết lập đầy đủ ngay",
  "先选择客户端；复制内容会自动带上本次 Token 和 Endpoint，无需再次替换占位符。平台只保存哈希，关闭后无法再次查看明文。": "Chọn client trước. Nội dung sao chép chứa token này và endpoint, không cần thay placeholder. Nền tảng chỉ lưu hash; không xem lại giá trị rõ sau khi đóng.",
  "还没有个人 Token，创建后即可接入 REST API 和 MCP。": "Chưa có token cá nhân. Tạo token để kết nối qua REST API và MCP.",
  "撤销后，正在使用这个 Token 的 API 和 MCP 客户端会立即失效。确定撤销？": "Client API và MCP dùng token này sẽ ngừng hoạt động ngay. Thu hồi?",
  "和平台助手对话：提需求、问进度、处理待确认": "Trò chuyện với trợ lý: tạo yêu cầu, kiểm tra tiến độ, xử lý rà soát",
