  "先建单，详情里继续澄清": "Tạo trước, làm rõ trong chi tiết",
  "提交回答并继续分析": "Gửi câu trả lời và tiếp tục",
  "本轮未完成，可重新分析，也可补充说明后提交。": "Lượt này chưa hoàn tất. Phân tích lại hoặc thêm chi tiết rồi gửi.",
  "还有要补充的，可以继续写": "Có gì khác cần bổ sung? Tiếp tục viết",
  "提交补充内容后会重新分析。": "Gửi bổ sung sẽ kích hoạt phân tích lại.",
  "信息已确认，可以建单；如需继续分析，请先补充说明。": "Thông tin đã xác nhận; sẵn sàng tạo. Để tiếp tục phân tích, thêm chi tiết trước.",
  "选择上方选项，或在这里补充说明": "Chọn tùy chọn ở trên hoặc thêm chi tiết tại đây",
  "请回答上方问题，也可以在这里补充说明": "Trả lời câu hỏi ở trên hoặc thêm chi tiết tại đây",
  "请根据上方分析补充说明": "Thêm chi tiết dựa trên phân tích ở trên",
  "回答已填写，可以提交并继续分析。": "Đã điền câu trả lời. Gửi để tiếp tục phân tích.",
  "请先选择答案或填写补充说明，再提交分析。": "Chọn câu trả lời hoặc thêm chi tiết trước khi gửi.",
  "请先填写问题的回答，再提交分析。": "Trả lời câu hỏi trước khi gửi.",
  "请先补充说明，或点击上方「重新生成问题」。": "Thêm chi tiết trước hoặc nhấp “Tạo lại câu hỏi” ở trên.",
  "没有固定轮数，分析师会按项目准入线判断。": "Không cố định số lượt; chuyên viên đánh giá theo ngưỡng dự án.",
  "分析师认为信息已经够用": "Chuyên viên đánh giá đã đủ thông tin",
  "点下方「平台需求」或「GitHub Issue」，建单后会按所选 SOP 启动。还要补充就写在输入框，再点「补充说明」。": "Nhấp “Yêu cầu nền tảng” hoặc “GitHub Issue” bên dưới; SOP đã chọn sẽ chạy sau khi tạo. Để bổ sung, nhập nội dung rồi nhấp “Thêm chi tiết”.",
  "你已确认可以建单": "Bạn đã xác nhận sẵn sàng tạo",
  "不必再等分析师达标。点下方「平台需求」或「GitHub Issue」，建单后会按所选 SOP 启动。": "Không cần chờ chuyên viên. Nhấp “Yêu cầu nền tảng” hoặc “GitHub Issue” bên dưới; SOP đã chọn sẽ chạy sau khi tạo.",
  "还在澄清，没有固定轮数": "Vẫn đang làm rõ, không cố định số lượt",
  "请先回答问题或补充说明，再提交分析。也可以点「按当前结论建单」，确认后建单并启动 SOP。": "Trả lời câu hỏi hoặc thêm chi tiết trước khi gửi. Hoặc nhấp “Tạo với phát hiện hiện tại” để tạo và khởi chạy SOP sau khi xác nhận.",
  "写清楚要做什么，选好仓库和要启动的 SOP。当前项目还没有绑定 GitHub 仓库。": "Mô tả công việc, rồi chọn kho mã và SOP để chạy. Dự án này chưa liên kết kho GitHub.",
  "当前项目还没绑定仓库，会按描述澄清。": "Dự án chưa liên kết kho mã; làm rõ từ mô tả.",
  "本轮未生成具体问题。你可以填写待确认信息或补充说明，也可以重新生成问题。": "Lượt này không có câu hỏi cụ thể. Điền thông tin còn thiếu hoặc thêm chi tiết, hoặc tạo lại câu hỏi.",
  "以下澄清只基于你的描述。要让 Agent 改你的代码，先在「项目配置」里添加仓库；不绑也能跑，改动只留在本次运行的工作区和产物里。": "Phần làm rõ bên dưới chỉ dựa trên mô tả của bạn. Để tác tử sửa mã, thêm kho mã trong cài đặt dự án trước. Vẫn chạy được khi không có kho; thay đổi nằm trong workspace và sản phẩm đầu ra của lượt chạy này.",
  "未能拉取代码仓库": "Không lấy được kho mã",
  "未能读取代码仓库「": "Không đọc được kho mã “",
  "以下澄清": "Phần làm rõ bên dưới ",
  "仅供参考，请先解决仓库拉取问题后再建单。": ". Chỉ để tham khảo; sửa vấn đề lấy kho mã trước khi tạo.",
  "未拉取到代码仓库「": "Không lấy được kho mã “",
  "本次分析不基于真实代码": "Phân tích này không dựa trên mã thực tế",
  "例如：个人主页增加徽章，需要兼容现有成就体系。\\n（Enter 换行；「开始分析」问清再建单并启动 SOP，「直接创建」跳过分析）": "Ví dụ: Thêm huy hiệu vào trang hồ sơ, tương thích hệ thống thành tích hiện có.\\n(Enter để xuống dòng; “Bắt đầu phân tích” làm rõ trước rồi tạo và chạy SOP; “Tạo ngay” bỏ qua phân tích)",
  "刷新后分析已中断，可继续。": "Phân tích bị gián đoạn do làm mới. Bạn có thể tiếp tục.",
  "刷新后分析已中断，可继续提问或直接创建。": "Phân tích bị gián đoạn do làm mới. Tiếp tục hỏi hoặc tạo ngay.",
  "新建需求已恢复，正在接上分析": "Đã khôi phục yêu cầu mới. Đang tiếp tục phân tích",
  "新建需求已恢复。进行中的分析已中断，可继续。": "Đã khôi phục yêu cầu mới. Phân tích đang chạy đã bị gián đoạn; bạn có thể tiếp tục.",
  "关闭会停止当前分析，并清空这次填写。下次打开「新建需求」会从空白开始。": "Đóng sẽ dừng phân tích hiện tại và xóa nội dung nhập. “Yêu cầu mới” sẽ trống ở lần sau.",
  "已停止，可修改需求后重新分析。": "Đã dừng. Sửa yêu cầu rồi phân tích lại.",
  "刷新后分析已结束，可继续提问或直接创建。": "Phân tích đã kết thúc sau khi làm mới. Tiếp tục hỏi hoặc tạo ngay.",
  "分析已结束，可继续提问或直接创建。": "Phân tích đã kết thúc. Tiếp tục hỏi hoặc tạo ngay.",
  "分析未返回有效问题，请再试一次": "Phân tích không trả câu hỏi hợp lệ. Thử lại",
  "信息已经够用。点下方按钮建单并启动 SOP。": "Thông tin đã đủ. Nhấp bên dưới để tạo và khởi chạy SOP.",
  "你已确认可以建单。点下方按钮建到平台或 GitHub Issue 并启动 SOP。": "Bạn đã xác nhận sẵn sàng. Nhấp bên dưới để tạo trên nền tảng hoặc dưới dạng GitHub Issue và khởi chạy SOP.",
  "分析未返回结果": "Phân tích không trả kết quả",
