  "可重新触发整条 SOP，不能接着这次运行重试": "Có thể kích hoạt lại toàn bộ SOP nhưng không thể thử lại lượt chạy này",
  "运行状态已失效，但节点仍在执行，建议取消": "Trạng thái lượt chạy đã cũ nhưng một bước vẫn đang chạy. Cân nhắc hủy",
