  "澄清未达标、门禁失败、运行失败或已中断的工作项会显示在这里。": "Các mục công việc chưa đủ làm rõ, không đạt điểm kiểm soát, lượt chạy thất bại hoặc gián đoạn xuất hiện tại đây.",
  "从 GitHub 同步或导入 Issue，或在本平台新建需求。": "Đồng bộ hoặc nhập Issue từ GitHub, hoặc tạo yêu cầu tại đây.",
