  "保存只改本平台记录，不会回写外部单据。": "Lưu chỉ cập nhật bản ghi nền tảng; không ghi lại vào mục bên ngoài.",
  "粘贴任意一种 GitHub 地址即可；集成分支用于检查多个 SOP 执行后是否存在合并冲突，可留空。": "Dán URL GitHub bất kỳ. Nhánh tích hợp kiểm tra xung đột hợp nhất giữa nhiều lượt chạy SOP; tùy chọn.",
  "当前项目还没有绑定代码仓库。": "Dự án này chưa liên kết kho mã nào.",
  "请粘贴 GitHub Issue 链接": "Dán liên kết GitHub Issue",
  "请至少选择一个代码仓库": "Chọn ít nhất một kho mã",
  "分，需要你补充澄清": " điểm, cần bạn làm rõ thêm",
  "该需求已有进行中的任务，确定额外发起一次重新运行吗？": "Yêu cầu này đã có tác vụ đang chạy. Vẫn bắt đầu lượt chạy lại khác?",
  "该需求已经处理过，确定整条 SOP 重新运行吗？": "Yêu cầu này đã được xử lý. Chạy lại toàn bộ SOP?",
