  "请先确认澄清结论后再触发 SOP": "Xác nhận tóm tắt làm rõ trước khi kích hoạt SOP",
  "需求澄清未达标，请先补充关键信息": "Làm rõ chưa đủ. Bổ sung thông tin chính trước",
  "模型凭据不可用": "Thông tin xác thực mô hình không khả dụng",
  "到个人设置粘贴 Claude / Codex / CodeBuddy 的 API Key，或用首次配置向导。CodeBuddy 中国站的 Key 需要把「CodeBuddy 网络环境」设为 internal（保存 Key 时会自动验证）。": "Dán API Key Claude / Codex / CodeBuddy trong Cài đặt hoặc dùng trình hướng dẫn thiết lập. Với key CodeBuddy Trung Quốc, đặt “Mạng CodeBuddy” thành internal (key được xác minh khi lưu).",
  "代码仓库鉴权失败": "Xác thực kho mã thất bại",
  "在个人设置填写可读写目标仓库的 GitHub Token（classic 勾选 repo）。": "Trong Cài đặt, thêm token GitHub có quyền đọc/ghi kho mã đích (classic: chọn repo).",
  "确认本机 Docker 可用，或把 SOP 沙箱改成 Local；首次会拉默认镜像，需等几分钟。": "Đảm bảo Docker khả dụng cục bộ hoặc chuyển sandbox SOP sang Cục bộ. Lần chạy đầu tải image mặc định và mất vài phút.",
  "检查项目是否绑定了正确仓库地址，以及网络能否访问 Git 主机。": "Kiểm tra dự án liên kết đúng URL kho mã và mạng có thể truy cập host Git.",
  "在「待我确认」重试本节点，或补充上下文后再跑。": "Thử lại bước này trong “Cần rà soát”, hoặc thêm ngữ cảnh và chạy lại.",
  "先看节点日志和产物；可补充上下文后重试失败节点，不必整条 SOP 重跑。": "Kiểm tra nhật ký bước và đầu ra trước. Có thể thêm ngữ cảnh và thử lại bước thất bại mà không chạy lại toàn bộ SOP.",
  "已取消的运行不能重试": "Không thể thử lại lượt chạy đã hủy",
  "可补充上下文后再从失败节点继续（例如单测失败用例名）。留空则直接重试，取消则中止。": "Có thể thêm ngữ cảnh rồi tiếp tục từ bước thất bại (ví dụ tên kiểm thử thất bại). Để trống để thử lại nguyên trạng; hủy để dừng.",
  "例如：修复某用例或调整依赖": "Ví dụ: Sửa ca kiểm thử hoặc điều chỉnh phụ thuộc",
  "已从失败节点继续，已完成的步骤不会重跑": "Đã tiếp tục từ bước thất bại; bước hoàn tất không chạy lại",
  "这条 SOP 已有进行中的任务，确定再次发起一个新运行吗？": "SOP này đã có tác vụ đang chạy. Vẫn bắt đầu lượt chạy mới khác?",
  "触发整条 SOP 确认": "Xác nhận kích hoạt toàn bộ SOP",
  "「触发」会把这条 SOP 从头再跑，已完成的步骤也会重做。要从失败节点继续请用「重试」。确定触发？": "“Kích hoạt” chạy lại SOP từ đầu, làm lại bước đã hoàn tất. Để tiếp tục từ bước thất bại, dùng “Thử lại”. Vẫn kích hoạt?",
  "这条 SOP 已经绑定": "SOP này đã được liên kết",
  "请先重新打开该需求，再触发 SOP": "Mở lại yêu cầu này trước khi kích hoạt SOP",
  "请先完成澄清再重新触发": "Hoàn tất làm rõ trước khi kích hoạt lại",
  "会整条 SOP 从头再开一条新运行，已完成步骤也会重做，旧记录还在。失败时若只想从失败点继续，请用「重试」。": "Thao tác này bắt đầu lượt chạy mới của toàn bộ SOP từ đầu, làm lại bước đã hoàn tất; giữ bản ghi cũ. Để chỉ tiếp tục từ điểm thất bại, dùng “Thử lại”.",
  "重新打开后，该工作项可以再次触发 SOP。确定继续？": "Sau khi mở lại, mục công việc này có thể kích hoạt SOP lần nữa. Tiếp tục?",
