  "及其下游重跑，上游已完成的步骤会保留。": " và các bước sau sẽ chạy lại; giữ các bước trước đã hoàn tất.",
  "补充说明会写进这次执行的上下文。": "Ghi chú bổ sung được thêm vào ngữ cảnh lượt chạy này.",
