  "点击右上角「添加自定义 MCP」创建个人专属配置。": "Nhấp “Thêm MCP tùy chỉnh” ở góc trên bên phải để tạo cấu hình cá nhân.",
  "切换到「MCP 市场」即可添加。": "Chuyển sang “Kho tiện ích MCP” để thêm.",
