  "连接 GitHub": "Kết nối GitHub",
  "连接后可选择仓库，用于克隆代码、创建分支和推送交付产物。": "Sau khi kết nối, bạn có thể chọn kho mã để clone mã nguồn, tạo nhánh và push sản phẩm bàn giao.",
