  "下一次运行你负责的任务时生效，可随时在列表中展开编辑。": "Có hiệu lực từ lần chạy tiếp theo của tác vụ do bạn phụ trách. Bạn có thể mở rộng mục trong danh sách để chỉnh sửa bất cứ lúc nào.",
