  "未认证": "Chưa xác thực",
  "登录后可在「个人配置」添加 Git 凭据和执行器。": "Sau khi đăng nhập, bạn có thể thêm thông tin xác thực Git và trình thực thi trong Cài đặt cá nhân.",
