  "还没有跑完的需求": "Chưa có yêu cầu nào hoàn tất",
  "前往 GitHub 申请个人访问令牌": "Truy cập GitHub để tạo token truy cập cá nhân",
  "复制令牌粘贴到下方，保存前会自动校验权限": "Sao chép và dán token bên dưới. Quyền sẽ được tự động xác minh trước khi lưu.",
  "保存前会先校验令牌有效性与权限": "Hiệu lực và quyền của token sẽ được xác minh trước khi lưu",
  "依赖私有仓库的 SOP 将无法克隆或推送仓库。": "Các SOP phụ thuộc vào kho mã riêng tư sẽ không thể clone hoặc push lên các kho mã đó.",
  "使用官方地址时，选择 CodeBuddy 账号所在的网络环境": "Khi dùng địa chỉ chính thức, chọn môi trường mạng của tài khoản CodeBuddy",
  "使用自定义网关时，填写网关提供的 Base URL 和 API Key": "Khi sử dụng gateway tùy chỉnh, nhập Base URL và API Key do gateway cung cấp",
  "请输入个人 ck_ key": "Nhập khóa ck_ cá nhân",
  "CodeBuddy 会使用可用的共享配置。其他 CLI 继续使用各自的凭据。": "CodeBuddy sẽ sử dụng cấu hình dùng chung khả dụng. Các CLI khác tiếp tục sử dụng thông tin xác thực riêng.",
  "AI 对话切换到 Codex 后可选用模型目录里的模型，SOP 在执行机器上以 Codex 运行的节点也使用它。目录为空时，未填 Base URL 使用 Codex 自带模型，填写后跟随服务发布的模型；也可以自己挑选、排序和命名。": "Khi chuyển cuộc trò chuyện AI sang Codex, bạn có thể chọn mô hình trong danh mục. Các bước SOP chạy Codex trên máy thực thi cũng dùng danh mục này. Nếu danh mục trống, khi không nhập Base URL sẽ dùng mô hình tích hợp của Codex; nếu đã nhập, sẽ dùng mô hình do dịch vụ cung cấp. Bạn cũng có thể tự chọn, sắp xếp và đặt tên mô hình.",
  "在模型服务商控制台创建 API Key": "Tạo API Key trong bảng điều khiển của nhà cung cấp mô hình",
  "如走代理或私有网关，记下服务地址": "Nếu dùng proxy hoặc gateway riêng, hãy ghi lại địa chỉ dịch vụ",
  "粘贴 Key，按需填写 Base URL；保存后可在模型目录里挑选 AI 对话的模型": "Dán khóa và nhập Base URL nếu cần. Sau khi lưu, bạn có thể chọn mô hình trò chuyện AI trong danh mục.",
  "以 Codex 运行的 SOP 节点将无法执行，Base URL 与模型目录一并清空。": "Các bước SOP sử dụng Codex sẽ không thể thực thi. Base URL và danh mục mô hình cũng sẽ bị xóa.",
  "AI 对话切换到 Claude Code 后可选用模型目录里的模型，SOP 在执行机器上以 Claude Code 运行的节点也使用它。目录为空时，未填 Base URL 使用 Claude Code 自带模型，填写后跟随服务发布的模型；也可以自己挑选、排序和命名。": "Khi chuyển cuộc trò chuyện AI sang Claude Code, bạn có thể chọn mô hình trong danh mục. Các bước SOP chạy Claude Code trên máy thực thi cũng dùng danh mục này. Nếu danh mục trống, khi không nhập Base URL sẽ dùng mô hình tích hợp của Claude Code; nếu đã nhập, sẽ dùng mô hình do dịch vụ cung cấp. Bạn cũng có thể tự chọn, sắp xếp và đặt tên mô hình.",
  "以 Claude Code 运行的 SOP 节点将无法执行，Base URL 与模型目录一并清空。": "Các bước SOP sử dụng Claude Code sẽ không thể thực thi. Base URL và danh mục mô hình cũng sẽ bị xóa.",
  "OpenCode 没有自己的模型服务，需要填写 Base URL。": "OpenCode không có dịch vụ mô hình riêng nên cần nhập Base URL.",
  "Cursor CLI 连接 Cursor 官方服务，可按账号获取模型。": "Cursor CLI kết nối tới dịch vụ chính thức của Cursor và có thể lấy danh sách mô hình theo tài khoản.",
  "登录 Cursor 控制台，在「Integrations → User API Keys」新建 Key": "Đăng nhập bảng điều khiển Cursor và tạo khóa tại Integrations → User API Keys",
  "前往 Cursor 创建 API Key": "Truy cập Cursor để tạo API Key",
  "粘贴到下方保存": "Dán bên dưới rồi lưu",
  "默认连接 Gemini 官方服务；选择 OpenAI 兼容网关时需要填写 Base URL。": "Mặc định kết nối dịch vụ chính thức của Gemini. Nếu chọn gateway tương thích OpenAI, cần nhập Base URL.",
  "OpenAI 兼容网关必填": "Bắt buộc đối với gateway tương thích OpenAI",
  "在 Google AI Studio 创建 Gemini API Key，或准备 OpenAI 兼容网关的 Key": "Tạo Gemini API Key trong Google AI Studio hoặc chuẩn bị khóa của gateway tương thích OpenAI",
  "前往 Google AI Studio": "Truy cập Google AI Studio",
  "走网关时记下网关地址": "Nếu dùng gateway, hãy ghi lại địa chỉ gateway",
  "粘贴 Key，选择协议；保存后可在模型目录里挑选 AI 对话的模型": "Dán khóa và chọn giao thức. Sau khi lưu, bạn có thể chọn mô hình trò chuyện AI trong danh mục.",
  "OpenAI 兼容网关（Chat Completions）": "Gateway tương thích OpenAI (Chat Completions)",
  "未填写 Base URL 时连接 Kimi Code 官方服务。": "Kết nối dịch vụ chính thức của Kimi Code nếu để trống Base URL.",
  "Pi 没有自己的模型服务，需要填写 Base URL。": "Pi không có dịch vụ mô hình riêng nên cần nhập Base URL.",
  "未填写 Base URL 时连接 DeepSeek 官方服务。": "Kết nối dịch vụ chính thức của DeepSeek nếu để trống Base URL.",
  "未填写 Base URL 时连接智谱 BigModel 的 Anthropic 兼容服务（Messages）。": "Kết nối dịch vụ tương thích Anthropic (Messages) của Zhipu BigModel nếu để trống Base URL.",
  "记下服务地址和它提供的接口协议": "Ghi lại địa chỉ dịch vụ và giao thức API mà dịch vụ cung cấp",
  "粘贴 Key，按需填写 Base URL 并选择协议；保存后可在模型目录里挑选 AI 对话的模型": "Dán khóa, nhập Base URL nếu cần và chọn giao thức. Sau khi lưu, bạn có thể chọn mô hình trò chuyện AI trong danh mục.",
  "，Base URL、协议与模型目录一并清空": ", đồng thời Base URL, giao thức và danh mục mô hình sẽ bị xóa",
